import { useRouteAnnouncer } from "../composables/route-announcer.js";
import { computed, defineComponent, h } from "vue";
//#region src/app/components/nuxt-route-announcer.ts
const NuxtRouteAnnouncer = defineComponent({
	name: "NuxtRouteAnnouncer",
	props: {
		atomic: {
			type: Boolean,
			default: false
		},
		politeness: {
			type: String,
			default: "polite"
		}
	},
	setup(props, { slots, expose }) {
		const { set, polite, assertive, message, politeness } = useRouteAnnouncer({ politeness: props.politeness });
		const role = computed(() => {
			if (politeness.value === "assertive") return "alert";
			if (politeness.value === "off") return;
			return "status";
		});
		expose({
			set,
			polite,
			assertive,
			message,
			politeness
		});
		return () => h("span", {
			class: "nuxt-route-announcer",
			style: { position: "absolute" }
		}, h("span", {
			"role": role.value,
			"aria-live": politeness.value,
			"aria-atomic": props.atomic,
			"style": {
				"border": "0",
				"clip": "rect(0 0 0 0)",
				"clip-path": "inset(50%)",
				"height": "1px",
				"width": "1px",
				"overflow": "hidden",
				"position": "absolute",
				"white-space": "nowrap",
				"word-wrap": "normal",
				"margin": "-1px",
				"padding": "0"
			}
		}, slots.default ? slots.default({ message: message.value }) : message.value));
	}
});
//#endregion
export { NuxtRouteAnnouncer as default };
